export class RegistroAcademico {
  materia;
  cuatrimestre;
  nota;
  estado;
  constructor(materia, cuatrimestre, nota, estado) {
    this.materia = materia;
    this.cuatrimestre = cuatrimestre;
    this.nota = nota;
    this.estado = estado;
  }
  getCuatrimestre() {
    return this.cuatrimestre;
  }
  estaAprobada() {
    return this.estado.estaAprobada();
  }
  getNota() {
    return this.nota;
  }
  getMateria() {
    return this.materia;
  }
  getEstado() {
    return this.estado;
  }
}
